/** Source boundary for the JavaScript generated by the exact native OpenNext build. */
declare module '*.open-next/worker.js' {
  /** Native fetch handler; opaque provider bindings are passed through unchanged. */
  const handler: {
    fetch(request: Request, env: Record<string, unknown>, context: unknown): Promise<Response>;
  };
  export default handler;
  /** Optional native cache/queue implementations retained for Wrangler's module linker. */
  export const DOQueueHandler: unknown;
  export const DOShardedTagCache: unknown;
  export const BucketCachePurge: unknown;
}
